EspFace::setPin.example:
face.setPin("1234");
face.setPin(nullptr);          // open device
face.setPin("4321", true);     // reset a client-changed PIN

EspFace::addUi.example:
auto& setupUi = face.addUi("setup");
setupUi.pin("");                    // no PIN for this UI
setupUi.header("WiFi setup");
face.ble().use(setupUi);

EspFace::set.example:
face.set("temp", 21.5f);
face.set("pump", true);
face.set("mode", 2);
face.set("rgb", (uint32_t)0x00ff00);
face.set("name", "Boiler");
face.set("joy", 10, -10);

WidgetRef::onChange.example:
ui.sw("pump", "Pump").onChange([](bool on) { digitalWrite(PUMP, on); });
ui.slider("t", "Target", 0, 100).onChange([](float v) { target = v; });
ui.text("name", "Name").onChange([](const String& s) { name = s; });

WidgetRef::bind.example:
bool pumpOn = false;
float target = 60;
ui.sw("pump", "Pump").bind(pumpOn);
ui.slider("target", "Target", 20, 90).bind(target);
